class APIHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/status":
            self.send_response(200)
            self.end_headers()
            self.wfile.write(json.dumps({"status": "ok"}).encode())
        else:
            self.send_response(404)
            self.end_headers()

import os
import stat

def check_permissions(path):
    st = os.stat(path)
    mode = stat.filemode(st.st_mode)
    return {"path": path, "mode": mode, "uid": st.st_uid}

def main():
    for p in ["/etc/passwd", "/etc/shadow", "/home/user/.ssh"]:
        if os.path.exists(p):
            print(check_permissions(p))

if __name__ == "__main__":
    main()

