#!/usr/bin/env python3
import os
import stat
import sys

def scan_directory(path):
    """Scan directory for permission anomalies"""
    print(f"[audit-perms] scanning {path}...")

    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        print(f"[ERROR] Directory not found: {path}")
        return

    for entry in entries:
        if entry.startswith('.'):
            continue

        fullpath = os.path.join(path, entry)

        try:
            st = os.stat(fullpath)
            mode = stat.S_IMODE(st.st_mode)

            # Check for SUID bit (4000)
            if mode & stat.S_ISUID:
                print(f"[WARN] SUID: {fullpath} (mode {oct(mode)})")

            # Check for world-writable (002)
            if mode & stat.S_IWOTH:
                print(f"[WARN] world-writable: {fullpath} (mode {oct(mode)})")

        except OSError as e:
            print(f"[ERROR] Cannot access {fullpath}: {e}")

def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "/home/user"
    print("[audit-perms] permission auditor v2.1")
    print(f"[audit-perms] scanning {target}...")
    scan_directory(target)
    print("[audit-perms] audit complete")

if __name__ == "__main__":
    main()
